CREATE OR REPLACE FUNCTION public.handle_new_user() RETURNS TRIGGER AS $$$ BEGIN BEGIN INSERT INTO public.profiles (id, user_id, email, first_name, last_name, created_at, updated_at) VALUES (new.id, new.id, new.email, COALESCE(new.raw_user_meta_data->>'first_name', ''), COALESCE(new.raw_user_meta_data->>'last_name', ''), now(), now()) ON CONFLICT (id) DO UPDATE SET email = EXCLUDED.email, first_name = CASE WHEN public.profiles.first_name = '' THEN EXCLUDED.first_name ELSE public.profiles.first_name END, last_name = CASE WHEN public.profiles.last_name = '' THEN EXCLUDED.last_name ELSE public.profiles.last_name END, updated_at = now(); EXCEPTION WHEN OTHERS THEN RAISE WARNING 'handle_new_user failed: %', SQLERRM; END; RETURN new; END; $$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public;
